def is_decimal(value):
    try:
        s = str(value)
        # Reject scientific notation explicitly
        if 'e' in s.lower():
            return False
        if '.' not in s:
            # No decimal part, zero decimal places
            return True
        integer_part, decimal_part = s.split('.', 1)
        # Check if decimal part length is <= 2 and both parts are numeric (allowing leading '-' in integer part)
        if integer_part.startswith('-'):
            integer_part = integer_part[1:]
        if not integer_part.isdigit():
            return False
        if not decimal_part.isdigit():
            return False
        return len(decimal_part) <= 2
    except Exception:
        return False

def is_Two_Alter(s: str) -> bool:
    if len(s) < 2:
        return True  # trivially alternating

    distinct_chars = set(s)
    if len(distinct_chars) != 2:
        return False

    for i in range(len(s) - 1):
        if s[i] == s[i+1]:
            return False

    return True

def max_sub_array_sum(arr, n):
    if n == 0:
        return 0

    max_so_far = arr[0]
    max_ending_here = arr[0]

    for i in range(1, n):
        max_ending_here = max(arr[i], max_ending_here + arr[i])
        max_so_far = max(max_so_far, max_ending_here)

    return max_so_far

def count_nums(arr):
    def signed_digits(n):
        s = str(abs(n))
        digits = [int(d) for d in s]
        if n < 0:
            digits[0] = -digits[0]
