def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    result_words = []

    for w in words:
        # Remove punctuation from the word
        cleaned = ''.join(ch for ch in w if ch.isalpha())
        if cleaned and is_prime(len(cleaned)):
            result_words.append(cleaned)

    return ' '.join(result_words)

