def special_factorial(n):
    from math import factorial
    result = 1
    for i in range(1, n+1):
        result *= factorial(i)
    return result

def even_odd_palindrome(n):
    def is_palindrome(x):
        s = str(x)
        return s == s[::-1]

    even_count = 0
    odd_count = 0

    for num in range(1, n + 1):
        if is_palindrome(num):
            if num % 2 == 0:
                even_count += 1
            else:
                odd_count += 1

    return (even_count, odd_count)

def correct_bracketing(brackets: str):
    count = 0
    for ch in brackets:
        if ch == '<':
            count += 1
        elif ch == '>':
            count -= 1
            if count < 0:
                return False
        else:
            # According to assumptions, input has only '<' and '>', so this is unreachable.
            pass
    return count == 0
